<?php
require_once dirname(__DIR__).'/app/helpers.php';require_auth();require_once dirname(__DIR__).'/app/Services/CardService.php';$svc=new CardService(Database::connection());$uid=(int)auth_user()['id'];$pdo=Database::connection();$cards=$svc->list($uid);$terminals=$pdo->query('SELECT id,terminal_code,location FROM atm_terminals WHERE status="active" ORDER BY id')->fetchAll();$error=null;$success=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$ref=$svc->atmWithdraw($uid,(int)$_POST['card_id'],trim($_POST['amount']),trim($_POST['pin']),(int)$_POST['terminal_id']);$success=t('Cash withdrawal completed successfully.').(' Reference: '.$ref);}catch(Throwable $e){$error=$e->getMessage();}}$pageTitle=t('ATM Withdrawal');$currentPage='cards';require __DIR__.'/partials/header.php';require __DIR__.'/partials/sidebar.php';?><div class="container py-5" style="max-width:760px"><div class="d-flex justify-content-between mb-4"><h2><?=e(t('ATM Withdrawal'))?></h2><a href="<?=url('cards.php')?>"><?=e(t('Cards'))?></a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="card border-0 shadow-sm"><div class="card-body"><form method="post" class="row g-3"><?=csrf_field()?><div class="col-12"><label class="form-label"><?=e(t('Card'))?></label><select name="card_id" class="form-select" required><?php foreach($cards as $c):?><option value="<?=$c['id']?>">•••• <?=e($c['last4'])?> — <?=e(tx_label($c['status']))?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label"><?=e(t('ATM Terminal'))?></label><select name="terminal_id" class="form-select" required><?php foreach($terminals as $t):?><option value="<?=$t['id']?>"><?=e($t['terminal_code'])?> — <?=e($t['location'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label"><?=e(t('Amount'))?></label><input name="amount" class="form-control" inputmode="decimal" required></div><div class="col-md-3"><label class="form-label"><?=e(t('Card PIN'))?></label><input name="pin" type="password" class="form-control" maxlength="6" required></div><div class="col-12"><button class="btn btn-primary"><?=e(t('Withdraw cash'))?></button></div></form></div></div></div><?php require __DIR__.'/partials/footer.php';?>
